def f(N: int, edges: List[Tuple[int, int]]): 
    # Implementing Floyd-Warshall algorithm to find longest distance
    inf = float('inf')
    dist = [[inf]*N for _ in range(N)]
    for x in range(N):
        dist[x][x] = 0
    for a, b in edges:
        dist[a-1][b-1] = 1
        dist[b-1][a-1] = 1
    print(dist)
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return len([1 for row in dist for i in row if i == 2])

